/* 消息之间的那段红线：从上一条的纽扣出发，接到下一个头像的圈。画在每条消息顶部的留白里 */
:root {
    --xh-bx: calc(var(--xh-av) * (0.62 - var(--xh-out)) + 12px);
    --xh-rx: calc(var(--xh-av) * (0.5 - var(--xh-out)) + 10px);
}
.mes::before {
    content: "";
    position: absolute;
    top: -12px;
    height: calc(var(--xh-gap) + 22px);
